import{_ as a,o as i,c as t,a6 as s}from"./chunks/framework.CMqVYFgm.js";const u=JSON.parse('{"title":"Compatibility","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/compatibility.md","filePath":"en/guide/compatibility.md","lastUpdated":1791540526000}'),n={name:"en/guide/compatibility.md"};function r(l,e,o,d,p,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h1><h2 id="package-and-api-versions" tabindex="-1">Package and API versions <a class="header-anchor" href="#package-and-api-versions" aria-label="Permalink to &quot;Package and API versions&quot;">​</a></h2><p>Install the Vue 3 package with:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue-fullscreen@next</span></span></code></pre></div><p>This API reference describes <code>4.0.0</code>, which is not yet published. The <code>next</code> channel currently provides <code>3.1.3</code>; some error events and package entry paths differ. Check <a href="https://www.npmjs.com/package/vue-fullscreen" target="_blank" rel="noreferrer">npm</a> for published versions.</p><h2 id="supported-environments" tabindex="-1">Supported environments <a class="header-anchor" href="#supported-environments" aria-label="Permalink to &quot;Supported environments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Support</th></tr></thead><tbody><tr><td>Vue</td><td><code>3.0+</code></td></tr><tr><td>Browser target</td><td>ES2018; Internet Explorer is not supported</td></tr><tr><td>SSR</td><td>Importing is supported; operations require the browser</td></tr></tbody></table><p>Examples using <code>&lt;script setup&gt;</code> require Vue 3.2+. For Vue 3.0/3.1, use the Options API example in <a href="/en/guide/getting-started">Getting started</a>. Vue 3.0&#39;s declarations may require <code>skipLibCheck</code> with modern TypeScript.</p><h2 id="model-events" tabindex="-1">Model events <a class="header-anchor" href="#model-events" aria-label="Permalink to &quot;Model events&quot;">​</a></h2><div class="language-vue vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">vue</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">fullscreen</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> v-model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Content&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">fullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&lt;!-- Equivalent explicit binding --&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">fullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model-value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">model-value</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">active </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $event</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p>The deprecated <code>fullscreen</code> / <code>update:fullscreen</code> pair is retained for compatibility. Do not control a component with conflicting model values.</p><h2 id="fullscreen-api-browser-support" tabindex="-1">Fullscreen API browser support <a class="header-anchor" href="#fullscreen-api-browser-support" aria-label="Permalink to &quot;Fullscreen API browser support&quot;">​</a></h2><p>Native fullscreen is provided by the browser. See <a href="https://caniuse.com/fullscreen" target="_blank" rel="noreferrer">Can I use: Fullscreen API</a> for version coverage and <a href="https://developer.mozilla.org/en-US/docs/Web/API/Element/requestFullscreen#browser_compatibility" target="_blank" rel="noreferrer">MDN&#39;s requestFullscreen compatibility table</a> for device restrictions. This overview was checked on 2026-10-09.</p><table tabindex="0"><thead><tr><th>Browser / device</th><th>Native fullscreen support</th></tr></thead><tbody><tr><td>Desktop Chrome / Edge</td><td>Standard API in Chrome 71+ and Edge 79+</td></tr><tr><td>Desktop Firefox</td><td>Standard API in 64+</td></tr><tr><td>macOS Safari</td><td>Standard API in 16.4+; earlier versions have partial prefixed support</td></tr><tr><td>iPad Safari</td><td>Standard API in iPadOS 16.4+, with device restrictions; earlier versions have partial prefixed support</td></tr><tr><td>iPhone Safari</td><td>No Fullscreen API for arbitrary elements; use page-only mode</td></tr><tr><td>Android Chrome / Firefox</td><td>Supported in current versions; see the support table for individual releases</td></tr><tr><td>Internet Explorer</td><td>IE 11 has partial native API support; this package does not support IE</td></tr></tbody></table><p>These versions describe the browser API, not this package&#39;s minimum browser versions or a promise of testing on each device. Package builds target ES2018. The underlying <code>screenfull</code> library handles some vendor prefixes, but cannot supply missing browser capabilities.</p><h3 id="safari-and-mobile-devices" tabindex="-1">Safari and mobile devices <a class="header-anchor" href="#safari-and-mobile-devices" aria-label="Permalink to &quot;Safari and mobile devices&quot;">​</a></h3><p>iPad fullscreen displays browser-provided exit controls, and system gestures such as swiping down may exit fullscreen. The iPhone video player&#39;s dedicated fullscreen feature does not provide native fullscreen for charts, ordinary <code>div</code> elements or the whole page. See the <a href="https://webkit.org/blog/13966/webkit-features-in-safari-16-4/" target="_blank" rel="noreferrer">WebKit release notes</a> for Safari 16.4 changes.</p><h3 id="internet-explorer" tabindex="-1">Internet Explorer <a class="header-anchor" href="#internet-explorer" aria-label="Permalink to &quot;Internet Explorer&quot;">​</a></h3><p>This package requires Vue 3 and does not support IE. Adding a <code>Promise</code> polyfill cannot supply the Proxy support required by Vue 3. For IE 11, use the separate <a href="/en/vue2/guide/compatibility">Vue 2 package and compatibility guide</a>.</p><h2 id="capability-detection-and-page-only-fallback" tabindex="-1">Capability detection and page-only fallback <a class="header-anchor" href="#capability-detection-and-page-only-fallback" aria-label="Permalink to &quot;Capability detection and page-only fallback&quot;">​</a></h2><p>Read <code>api.isEnabled</code> in the browser to check whether the current document allows native fullscreen. It does not indicate whether fullscreen is active or guarantee that the next request will succeed.</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { api } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vue-fullscreen&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Read after mount or during a user interaction</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nativeAvailable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> api.isEnabled</span></span></code></pre></div><ul><li>When native fullscreen is unavailable, the component, directive and API fall back to page-only mode.</li><li>Explicitly setting <code>pageOnly: true</code> (<code>page-only</code> on the component) always uses page-only mode.</li><li>If the native capability is available but a request is rejected, the library reports the error and restores the DOM without silently falling back. Catch API Promise rejections; use the component&#39;s <code>error</code> event or the directive&#39;s <code>fullscreen-error</code> event.</li></ul><p>Page-only mode keeps the browser toolbar and fills only the current document&#39;s viewport. Inside an iframe, it fills the frame. <code>teleport</code> moves the target to that document&#39;s <code>body</code>; it cannot escape the iframe boundary.</p><h2 id="user-activation-and-iframe-permissions" tabindex="-1">User activation and iframe permissions <a class="header-anchor" href="#user-activation-and-iframe-permissions" aria-label="Permalink to &quot;User activation and iframe permissions&quot;">​</a></h2><p>Native fullscreen must be triggered by a click, touch or key interaction. Avoid waiting for a network request before calling the API, as user activation may expire.</p><p>An embedded document needs fullscreen permission, for example:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/example/&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allow</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;fullscreen&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> allowfullscreen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">iframe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>The parent document&#39;s <code>Permissions-Policy</code> can still restrict fullscreen. An iframe attribute cannot override a stricter response-header policy.</p><h2 id="exiting-fullscreen-and-tracking-state" tabindex="-1">Exiting fullscreen and tracking state <a class="header-anchor" href="#exiting-fullscreen-and-tracking-state" aria-label="Permalink to &quot;Exiting fullscreen and tracking state&quot;">​</a></h2><p>Users can press Esc or use browser exit controls. Loading another document, reloading, switching tabs or changing applications with Alt-Tab can also exit native fullscreen. Behavior depends on the browser and operating system; see the <a href="https://developer.mozilla.org/en-US/docs/Web/API/Fullscreen_API/Guide#things_your_users_want_to_know" target="_blank" rel="noreferrer">MDN fullscreen guide</a>.</p><p>Do not assume your exit button is the only source of state changes. The component synchronizes actual state through <code>v-model</code>; use <code>callback</code> to track API and directive state. Page-only mode does not necessarily exit when changing applications, so keep an exit button visible.</p><p>SPA route changes differ from loading another document: fullscreen can continue while the outer target remains mounted, whereas unmounting the fullscreen component exits it. See the <a href="/en/examples">examples</a>.</p><h2 id="ssr" tabindex="-1">SSR <a class="header-anchor" href="#ssr" aria-label="Permalink to &quot;SSR&quot;">​</a></h2><p>Importing the package does not require a browser, but fullscreen operations such as <code>request()</code> do. Obtain DOM elements after mount and request fullscreen during a user interaction.</p>`,35)])])}const k=a(n,[["render",r]]);export{u as __pageData,k as default};
